package com.gomgomapps.math.core;
import java.util.*;import java.math.*;import org.junit.Test;import static org.junit.Assert.*;
public class YearSixEstimateCheckTest {
 static int round(int n,int u){return BigDecimal.valueOf(n).divide(BigDecimal.valueOf(u),0,RoundingMode.HALF_UP).intValueExact()*u;}
 @Test public void gradeSixFreshLargeNumbersAndPublicVerdicts(){var pack=GlobalCurriculum.packs("GB").stream().filter(p->p.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();for(String id:List.of(EstimateCalculationCheck.ADD,EstimateCalculationCheck.SUB)){assertTrue(pack.inGrade(id,6));assertEquals(1000000,GlobalCurriculum.limits(pack.id,id,5).wholeMaximum(999));CurriculumLimits limits=GlobalCurriculum.limits(pack.id,id,6);assertEquals(10000000,limits.wholeMaximum(999));Generator g=new Generator(new Random(200));List<String> recent=new ArrayList<>();boolean large=false,in=false,out=false;Set<Integer> units=new HashSet<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=EstimateCalculationCheck.read(q);assertNotNull(v);units.add(v[3]);large|=v[0]>1000000||v[1]>1000000;int e=id.equals(EstimateCalculationCheck.ADD)?round(v[0],v[3])+round(v[1],v[3]):round(v[0],v[3])-round(v[1],v[3]);boolean inside=Math.abs(v[2]-e)<=v[3];in|=inside;out|=!inside;q.answers=new String[]{"poison","poison"};q.expression="poison";Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(""+e,inside?"0":"1")).correct());assertEquals(0,c.check(q,List.of(),List.of(""+(e+1),inside?"0":"1")).index);assertEquals(1,c.check(q,List.of(),List.of(""+e,inside?"1":"0")).index);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(17,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertTrue(large&&in&&out);assertEquals(Set.of(10,100,1000,10000,100000,1000000,10000000),units);}}
 @Test public void tenMillionBoundaryIndexesAndPlausibilityNotEquality(){int[] units={10,100,1000,10000,100000,1000000,10000000};for(String id:List.of(EstimateCalculationCheck.ADD,EstimateCalculationCheck.SUB)){long count=LargeEstimateSupply.count(id,10000000,units);for(long index:new long[]{0,1,count/2,count-2,count-1})assertNotNull(EstimateCalculationCheck.read(LargeEstimateSupply.indexed(id,10000000,units,index)));for(int a:new int[]{0,4999999,5000000,9999999,10000000})for(int b:new int[]{0,4999999,5000000,9999999,10000000}){if(id.equals(EstimateCalculationCheck.SUB)&&a<b)continue;for(int unit:units){int e=id.equals(EstimateCalculationCheck.ADD)?round(a,unit)+round(b,unit):round(a,unit)-round(b,unit);for(int delta:new int[]{unit,unit+1})assertTrue(new Checker().check(EstimateCalculationCheck.make(id,a,b,e+delta,unit),List.of(),List.of(""+e,delta==unit?"0":"1")).correct());}}}Question q=EstimateCalculationCheck.make(EstimateCalculationCheck.ADD,9999999,9999999,20000000,10000000);assertTrue(new Checker().check(q,List.of(),List.of("20000000","0")).correct());assertNotEquals(19999998,20000000);q.prompt=q.prompt.replace("9999999","10000001");assertNull(EstimateCalculationCheck.read(q));}
}
